import{_ as a,a0 as o,w as n,s as p,I as s,x as i,a1 as l,A as d,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何使用命令列檢查 Linux 上的磁盤空間 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用命令列檢查 Linux 上的磁盤空間 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用命令列檢查 Linux 上的磁盤空間 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用命令列檢查 Linux 上的磁盤空間 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180622 How to Check Disk Space on Linux from the Command line","title":"如何使用命令列檢查 Linux 上的磁盤空間","tag":"201808","desc":""},"relativePath":"201808/20180622 How to Check Disk Space on Linux from the Command line.md","filePath":"[post].md"}'),r={name:"201808/20180622 How to Check Disk Space on Linux from the Command line.md"};function c(k,e,m,h,g,f){const t=o("Link");return n(),p("div",null,[e[21]||(e[21]=s("h1",{id:"如何使用命令列檢查-linux-上的磁盤空間",tabindex:"-1"},[i("如何使用命令列檢查 Linux 上的磁盤空間 "),s("a",{class:"header-anchor",href:"#如何使用命令列檢查-linux-上的磁盤空間","aria-label":"Permalink to “如何使用命令列檢查 Linux 上的磁盤空間”"},"​")],-1)),e[22]||(e[22]=s("blockquote",null,[s("p",null,"Linux 提供了所有必要的工具來幫助你確切地發現你的驅動器上剩餘多少空間。Jack 在這裏展示瞭如何做。")],-1)),e[23]||(e[23]=s("p",null,[s("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/diskspace-main.jpg?itok=t9Oxxc9X",alt:""})],-1)),e[24]||(e[24]=s("p",null,"快速提問：你的驅動器剩餘多少剩餘空間？一點點還是很多？接下來的提問是：你知道如何找出這些剩餘空間嗎？如果你碰巧使用的是 GUI 桌面（ 例如 GNOME、KDE、Mate、Pantheon 等 ），則任務可能非常簡單。但是，當你要在一個沒有 GUI 桌面的服務器上查詢剩餘空間，你該如何去做呢？你是否要為這個任務安裝相應的軟件工具？答案是絕對不是。在 Linux 中，具備查找驅動器上的剩餘磁盤空間的所有工具。事實上，有兩個非常容易使用的工具。",-1)),s("p",null,[e[1]||(e[1]=i("在本文中，我將演示這些工具。我將使用 ",-1)),l(t,{href:"https://elementary.io/"},{default:d(()=>[...e[0]||(e[0]=[i("Elementary OS",-1)])]),_:1}),e[2]||(e[2]=i("（LCTT譯註：Elementary OS 是基於 Ubuntu 精心打磨美化的桌面 Linux 發行版 ），它還包括一個 GUI 方式，但我們將限制自己僅使用命令列。好消息是這些命令列工具隨時可用於每個 Linux 發行版。在我的測試系統中，連接了許多的驅動器（內部的和外部的）。使用的命令與連接驅動器的位置無關，僅僅與驅動器是否已經掛載好並且對操作系統可見有關。",-1))]),e[25]||(e[25]=u('<p>言歸正傳，讓我們來試試這些工具。</p><h3 id="df" tabindex="-1">df <a class="header-anchor" href="#df" aria-label="Permalink to “df”">​</a></h3><p><code>df</code> 命令是我第一個用於在 Linux 上查詢驅動器空間的工具，時間可以追溯到 20 世紀 90 年代。它的使用和報告結果非常簡單。直到今天，<code>df</code> 還是我執行此任務的首選命令。此命令有幾個選項開關，對於基本的報告，你實際上只需要一個選項。該命令是 <code>df -H</code> 。<code>-H</code> 選項開關用於將 <code>df</code> 的報告結果以人類可讀的格式進行顯示。<code>df -H</code> 的輸出包括：已經使用了的空間量、可用空間、空間使用的百分比，以及每個磁盤連接到系統的掛載點（圖 1）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/diskspace_1.jpg?itok=aJa8AZAM" alt="df output"></p><p><em>圖 1：Elementary OS 系統上 <code>df -H</code> 命令的輸出結果</em></p><p>如果你的驅動器列表非常長並且你只想查看單個驅動器上使用的空間，該怎麼辦？對於 <code>df</code> 這沒問題。我們來看一下位於 <code>/dev/sda1</code> 的主驅動器已經使用了多少空間。為此，執行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>df -H /dev/sda1</span></span></code></pre></div><p>輸出將限於該驅動器（圖 2）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/diskspace_2.jpg?itok=_PAq3kxC" alt="disk usage"></p><p><em>圖 2：一個單獨驅動器空間情況</em></p><p>你還可以限制 <code>df</code> 命令結果報告中顯示指定的字段。可用的字段包括：</p><ul><li><code>source</code> — 文件系統的來源（LCTT譯註：通常為一個設備，如 <code>/dev/sda1</code> ）</li><li><code>size</code> — 塊總數</li><li><code>used</code> — 驅動器已使用的空間</li><li><code>avail</code> — 可以使用的剩餘空間</li><li><code>pcent</code> — 驅動器已經使用的空間佔驅動器總空間的百分比</li><li><code>target</code> —驅動器的掛載點</li></ul><p>讓我們顯示所有驅動器的輸出，僅顯示 <code>size</code> ，<code>used</code> ，<code>avail</code> 字段。對此的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>df -H --output=size,used,avail</span></span></code></pre></div><p>該命令的輸出非常簡單（ 圖 3 ）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/diskspace_3.jpg?itok=51m8I-Vu" alt="output"></p><p><em>圖 3：顯示我們驅動器的指定輸出</em></p><p>這裏唯一需要注意的是我們不知道該輸出的來源，因此，我們要把 <code>source</code> 加入命令中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>df -H --output=source,size,used,avail</span></span></code></pre></div><p>現在輸出的信息更加全面有意義（圖 4）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/diskspace_4.jpg?itok=SuwgueN3" alt="source"></p><p><em>圖 4：我們現在知道了磁盤使用情況的來源</em></p><h3 id="du" tabindex="-1">du <a class="header-anchor" href="#du" aria-label="Permalink to “du”">​</a></h3><p>我們的下一個命令是 <code>du</code> 。 正如您所料，這代表<ruby>磁盤使用情況<rt>disk usage</rt></ruby>。 <code>du</code> 命令與 <code>df</code> 命令完全不同，因為它報告目錄而不是驅動器的空間使用情況。 因此，您需要知道要檢查的目錄的名稱。 假設我的計算機上有一個包含虛擬機文件的目錄。 那個目錄是 <code>/media/jack/HALEY/VIRTUALBOX</code> 。 如果我想知道該特定目錄使用了多少空間，我將運行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>du -h /media/jack/HALEY/VIRTUALBOX</span></span></code></pre></div><p>上面命令的輸出將顯示目錄中每個文件佔用的空間（圖 5）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/diskspace_5.jpg?itok=XfS4s7Zq" alt="du command"></p><p><em>圖 5 在特定目錄上運行 <code>du</code> 命令的輸出</em></p><p>到目前為止，這個命令並沒有那麼有用。如果我們想知道特定目錄的總使用量怎麼辦？幸運的是，<code>du</code> 可以處理這項任務。對於同一目錄，命令將是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>du -sh /media/jack/HALEY/VIRTUALBOX/</span></span></code></pre></div><p>現在我們知道了上述目錄使用存儲空間的總和（圖 6）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/diskspace_6.jpg?itok=r71qICyG" alt="space used"></p><p><em>圖 6：我的虛擬機文件使用存儲空間的總和是 559GB</em></p><p>您還可以使用此命令查看父項的所有子目錄使用了多少空間，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>du -h /media/jack/HALEY</span></span></code></pre></div><p>此命令的輸出見（圖 7），是一個用於查看各子目錄佔用的驅動器空間的好方法。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/diskspace_7.jpg?itok=PtDe4q5y" alt="directories"></p><p><em>圖 7：子目錄的存儲空間使用情況</em></p><p><code>du</code> 命令也是一個很好的工具，用於查看使用系統磁盤空間最多的目錄列表。執行此任務的方法是將 <code>du</code> 命令的輸出通過管道傳遞給另外兩個命令：<code>sort</code> 和 <code>head</code> 。下面的命令用於找出驅動器上佔用存儲空間最大的前 10 個目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>du -a /media/jack | sort -n -r |head -n 10</span></span></code></pre></div><p>輸出將以從大到小的順序列出這些目錄（圖 8）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/diskspace_8.jpg?itok=v9E1SFcC" alt="top users"></p><p><em>圖 8：使用驅動器空間最多的 10 個目錄</em></p><h3 id="沒有你想像的那麼難" tabindex="-1">沒有你想像的那麼難 <a class="header-anchor" href="#沒有你想像的那麼難" aria-label="Permalink to “沒有你想像的那麼難”">​</a></h3><p>查看 Linux 系統上掛載的驅動器的空間使用情況非常簡單。只要你將你的驅動器掛載在 Linux 系統上，使用 <code>df</code> 命令或 <code>du</code> 命令在報告必要信息方面都會非常出色。使用 <code>df</code> 命令，您可以快速查看磁盤上總的空間使用量，使用 <code>du</code> 命令，可以查看特定目錄的空間使用情況。對於每一個 Linux 系統的管理員來説，這兩個命令的結合使用是必須掌握的。</p>',45)),s("p",null,[e[4]||(e[4]=i("而且，如果你沒有注意到，我最近介紹了",-1)),l(t,{href:"https://www.linux.com/learn/5-commands-checking-memory-usage-linux"},{default:d(()=>[...e[3]||(e[3]=[i("查看 Linux 上內存使用情況的方法",-1)])]),_:1}),e[5]||(e[5]=i("。總之，這些技巧將大力幫助你成功管理 Linux 服務器。",-1))]),e[26]||(e[26]=s("p",null,"通過 Linux Foundation 和 edX 免費提供的 “Linux 簡介” 課程，瞭解更多有關 Linux 的信息。",-1)),e[27]||(e[27]=s("hr",null,null,-1)),s("p",null,[e[7]||(e[7]=i("via: ",-1)),l(t,{href:"https://www.linux.com/learn/intro-to-linux/2018/6how-check-disk-space-linux-command-line"},{default:d(()=>[...e[6]||(e[6]=[i("https://www.linux.com/learn/intro-to-linux/2018/6how-check-disk-space-linux-command-line",-1)])]),_:1})]),s("p",null,[e[12]||(e[12]=i("作者：",-1)),l(t,{href:"https://www.linux.com/users/jlwallen"},{default:d(()=>[...e[8]||(e[8]=[i("Jack Wallen",-1)])]),_:1}),e[13]||(e[13]=i(" 選題：",-1)),l(t,{href:"https://github.com/lujun9972"},{default:d(()=>[...e[9]||(e[9]=[i("lujun9972",-1)])]),_:1}),e[14]||(e[14]=i(" 譯者：",-1)),l(t,{href:"https://github.com/SunWave"},{default:d(()=>[...e[10]||(e[10]=[i("SunWave",-1)])]),_:1}),e[15]||(e[15]=i(" 校對：",-1)),l(t,{href:"https://github.com/wxy"},{default:d(()=>[...e[11]||(e[11]=[i("wxy",-1)])]),_:1})]),s("p",null,[e[18]||(e[18]=i("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...e[16]||(e[16]=[i("LCTT",-1)])]),_:1}),e[19]||(e[19]=i(" 原創編譯，",-1)),l(t,{href:"https://linux.cn/"},{default:d(()=>[...e[17]||(e[17]=[i("Linux中國",-1)])]),_:1}),e[20]||(e[20]=i(" 榮譽推出",-1))])])}const C=a(r,[["render",c]]);export{w as __pageData,C as default};
